 * Deterministic, dependency-free foundation module (generated baseline — hand-polish deepens domain logic).
 * @typedef {{ id: string, occurredAt: string, quantity: number, attributes?: Record<string, string> }} DeterminismHardeningPass12Input
 * @typedef {{ code: string, severity: "info" | "warning" | "critical", evidence: string[] }} DeterminismHardeningPass12Finding
 * @typedef {{ subjectId: string, status: "accepted" | "blocked", findings: DeterminismHardeningPass12Finding[] }} DeterminismHardeningPass12Result
 */

/**
 * Evaluate one input against the determinism hardening pass 12 policy.
 * @param {DeterminismHardeningPass12Input} input
 * @returns {DeterminismHardeningPass12Result}
 */
export function evaluateDeterminismHardeningPass12(input) {
	const findings = [];
	if (!input || typeof input.id !== "string" || input.id.length === 0) {
		return { subjectId: "unknown", status: "blocked", findings: [{ code: "determinism-hardening-pass-12/missing-id", severity: "critical", evidence: ["input.id is required"] }] };
	}
	if (!Number.isFinite(input.quantity) || input.quantity < 0) {
		findings.push({ code: "determinism-hardening-pass-12/quantity-range", severity: "critical", evidence: [`quantity ${input.quantity} is outside [0, ∞)`] });
	}
	if (!/^\d{4}-\d{2}-\d{2}T/.test(input.occurredAt ?? "")) {
		findings.push({ code: "determinism-hardening-pass-12/timestamp-shape", severity: "warning", evidence: [`occurredAt ${String(input.occurredAt)} is not ISO-8601`] });
	}
	const blocked = findings.some((finding) => finding.severity === "critical");
	if (findings.length === 0) {
		findings.push({ code: "determinism-hardening-pass-12/clean", severity: "info", evidence: ["all deterministic checks passed"] });
	}
	return { subjectId: input.id, status: blocked ? "blocked" : "accepted", findings };
}

import test from "node:test";
import assert from "node:assert/strict";
import { evaluateDeterminismHardeningPass12 } from "../src/determinism-hardening-pass-12.mjs";

test("determinism-hardening-pass-12: accepts a clean input with evidence", () => {
	const result = evaluateDeterminismHardeningPass12({ id: "subject-1", occurredAt: "2026-01-01T00:00:00.000Z", quantity: 1 });
	assert.equal(result.status, "accepted");
	assert.ok(result.findings.length > 0);
	assert.ok(result.findings.every((finding) => finding.evidence.length > 0));
});

test("determinism-hardening-pass-12: blocks negative quantity with a critical finding", () => {
	const result = evaluateDeterminismHardeningPass12({ id: "subject-2", occurredAt: "2026-01-01T00:00:00.000Z", quantity: -1 });
	assert.equal(result.status, "blocked");
	assert.ok(result.findings.some((finding) => finding.severity === "critical"));
});

